INSERT INTO resource_translations (resource_id, language, title, summary, body, created_at, updated_at)
SELECT id, 'th', 'บทใคร่ครวญพระกิตติคุณ 1 ตุลาคม', '', 'วันนี้เราต้องกลับมามองชีวิตผ่านพระกิตติคุณอีกครั้ง บางครั้งพระคุณของพระเจ้าไม่ใช่ความสบาย แต่เป็นการช่วยกู้ที่เจ็บปวด ความจริงนี้ไม่ได้เป็นเพียงความรู้ทางศาสนา แต่เป็นแสงสว่างที่ช่วยให้เรามองหัวใจของตนเองและสถานการณ์ตรงหน้าอย่างถูกต้อง

บ่อยครั้งเราสะดุดตรงนี้ เราต้องการให้พระเจ้าปลดปล่อยจากสถานการณ์มากกว่าช่วยหัวใจจากรูปเคารพ เราอาจยังทำกิจกรรมฝ่ายวิญญาณได้ แต่ภายในใจกลับถูกความกลัว ความต้องการของตนเอง หรือสิ่งที่มองเห็นนำทางมากกว่าพระเจ้า

แต่พระคุณของพระเจ้าไม่ปล่อยเราไว้เช่นนั้น พระเจ้าทรงรักมากพอที่จะดึงเราออกจากสิ่งที่อันตราย พระคริสต์ไม่ได้เพียงให้อภัยเรา แต่ทรงนำเราออกจากการพึ่งตนเอง เพื่อให้เรากลับมาพักในพระองค์

ดังนั้น อย่ามองความยากทุกอย่างเป็นการขาดความรัก แต่ให้ถามว่าพระเจ้ากำลังช่วยใจเราอย่างไร นี่คือการดำเนินชีวิตด้วยความเชื่ออย่างธรรมดาในวันนี้ คือซื่อสัตย์ต่อความจริงเรื่องบาป และยึดมั่นในพระคุณที่เพียงพอของพระคริสต์

คำอธิษฐาน

พระบิดาผู้ทรงรักและทรงสัตย์ซื่อ ข้าพระองค์สรรเสริญพระองค์ เพราะพระองค์ทรงเข้ามาหาข้าพระองค์ด้วยพระคุณ ไม่ใช่ด้วยการกล่าวโทษ โปรดอภัยเมื่อข้าพระองค์ลืมความจริงนี้และปล่อยให้ความกลัว ความต้องการของตนเอง หรือความคิดของโลกครอบงำใจ

ขอบพระคุณพระเยซูคริสต์ ผู้ทรงสิ้นพระชนม์และทรงเป็นขึ้นจากความตาย เพื่อประทานการอภัย ชีวิตใหม่ และกำลังแก่ข้าพระองค์ ขอให้ข้าพระองค์ยอมรับการดูแลของพระองค์ แม้ไม่สบายต่อใจ ขอให้พระวิญญาณบริสุทธิ์ทรงทำให้ใจของข้าพระองค์อ่อนลง เชื่อฟัง และเดินในพระคุณของพระองค์วันนี้

