INSERT INTO resource_translations (resource_id, language, title, summary, body, created_at, updated_at)
SELECT id, 'th', 'บทใคร่ครวญพระกิตติคุณ 22 ตุลาคม', '', 'วันนี้เราต้องกลับมามองชีวิตผ่านพระกิตติคุณอีกครั้ง พระคุณของพระเจ้าไม่หยุดทำงานเมื่อเราอ่อนแอ ความจริงนี้ไม่ได้เป็นเพียงความรู้ทางศาสนา แต่เป็นแสงสว่างที่ช่วยให้เรามองหัวใจของตนเองและสถานการณ์ตรงหน้าอย่างถูกต้อง

บ่อยครั้งเราสะดุดตรงนี้ เราคิดว่าความไม่เชื่อฟังหรือความสงสัยทำให้พระเจ้าหันหลัง เราอาจยังทำกิจกรรมฝ่ายวิญญาณได้ แต่ภายในใจกลับถูกความกลัว ความต้องการของตนเอง หรือสิ่งที่มองเห็นนำทางมากกว่าพระเจ้า

แต่พระคุณของพระเจ้าไม่ปล่อยเราไว้เช่นนั้น พระคุณจากพระหัตถ์ของพระเยซูยังตักเตือน ฟื้นฟู และเลี้ยงดูเรา พระคริสต์ไม่ได้เพียงให้อภัยเรา แต่ทรงนำเราออกจากการพึ่งตนเอง เพื่อให้เรากลับมาพักในพระองค์

ดังนั้น วันนี้ให้ความล้มเหลวพาเราเข้าหาพระคุณ ไม่ใช่หนีจากพระเจ้า นี่คือการดำเนินชีวิตด้วยความเชื่ออย่างธรรมดาในวันนี้ คือซื่อสัตย์ต่อความจริงเรื่องบาป และยึดมั่นในพระคุณที่เพียงพอของพระคริสต์

คำอธิษฐาน

พระบิดาผู้ทรงรักและทรงสัตย์ซื่อ ข้าพระองค์สรรเสริญพระองค์ เพราะพระองค์ทรงเข้ามาหาข้าพระองค์ด้วยพระคุณ ไม่ใช่ด้วยการกล่าวโทษ โปรดอภัยเมื่อข้าพระองค์ลืมความจริงนี้และปล่อยให้ความกลัว ความต้องการของตนเอง หรือความคิดของโลกครอบงำใจ

ขอบพระคุณพระเยซูคริสต์ ผู้ทรงสิ้นพระชนม์และทรงเป็นขึ้นจากความตาย เพื่อประทานการอภัย ชีวิตใหม่ และกำลังแก่ข้าพระองค์ ขอให้ข้าพระองค์เชื่อว่าพระคุณของพระองค์ลึกกว่าบาปของข้าพระองค์ ขอให้พระวิญญาณบริสุทธิ์ทรงทำให้ใจของข้าพระองค์อ่อนลง เชื่อฟัง และเดินในพระคุณของพระองค์วันนี้

